import{_ as t,o,c as a,a1 as s}from"./chunks/framework.DceXOx8u.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/troubleshooting"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/troubleshooting"}]]},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),i={name:"guide/troubleshooting.md"};function n(r,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>The errors people hit most often, what they mean and how to fix them. Search this page for the exact message you see (most botmesh errors name the option or the package involved).</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><h3 id="err-pnpm-ignored-builds-or-native-module-was-never-built" tabindex="-1"><code>ERR_PNPM_IGNORED_BUILDS</code> or &quot;native module was never built&quot; <a class="header-anchor" href="#err-pnpm-ignored-builds-or-native-module-was-never-built" aria-label="Permalink to &quot;`ERR_PNPM_IGNORED_BUILDS` or &quot;native module was never built&quot;&quot;">​</a></h3><p>pnpm 10 and later do not run the install scripts of dependencies until you decide which ones may run. pnpm 11 stops the install with <code>ERR_PNPM_IGNORED_BUILDS</code>; pnpm 10 installs without them, and the failure shows up later.</p><p>Decide once in <code>pnpm-workspace.yaml</code> (or run <code>pnpm approve-builds</code>) and reinstall:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowBuilds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  better-sqlite3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # native binary of @botmesh/sqlite-store: must run</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;@whiskeysockets/baileys&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # only a Node.js version check</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  protobufjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # only a version notice</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ffmpeg-static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # only if you installed it for Baileys voice notes</span></span></code></pre></div><p>On pnpm 10 the equivalent is <code>onlyBuiltDependencies: [better-sqlite3]</code>. If <code>better-sqlite3</code> was skipped, <code>SQLiteStore</code> throws <code>better-sqlite3 is installed but its native module was never built</code>. npm runs every install script, so it needs none of this.</p><h3 id="the-process-aborts-with-assertion-failed-env-nullptr" tabindex="-1">The process aborts with <code>Assertion failed: (env) != nullptr</code> <a class="header-anchor" href="#the-process-aborts-with-assertion-failed-env-nullptr" aria-label="Permalink to &quot;The process aborts with `Assertion failed: (env) != nullptr`&quot;">​</a></h3><p>You are on Node.js 24.19 or later with <code>better-sqlite3</code> 11 or 12. A Node.js regression (<a href="https://github.com/nodejs/node/issues/65446" target="_blank" rel="noreferrer">nodejs/node#65446</a>) can abort the process in <code>RemoveEnvironmentCleanupHook</code> when a prepared statement is garbage-collected. Install <code>better-sqlite3</code> 13, which is built on N-API and not affected:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> better-sqlite3@^13</span></span></code></pre></div><h3 id="built-for-another-node-js-version-node-module-version" tabindex="-1">&quot;built for another Node.js version&quot; / <code>NODE_MODULE_VERSION</code> <a class="header-anchor" href="#built-for-another-node-js-version-node-module-version" aria-label="Permalink to &quot;&quot;built for another Node.js version&quot; / `NODE_MODULE_VERSION`&quot;">​</a></h3><p>A native module (usually <code>better-sqlite3</code>) was compiled for the Node.js you had before an upgrade. Rebuild it with the Node.js that runs the bot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebuild</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> better-sqlite3</span></span></code></pre></div><h3 id="err-require-esm-or-require-is-not-defined" tabindex="-1"><code>ERR_REQUIRE_ESM</code> or <code>require is not defined</code> <a class="header-anchor" href="#err-require-esm-or-require-is-not-defined" aria-label="Permalink to &quot;`ERR_REQUIRE_ESM` or `require is not defined`&quot;">​</a></h3><p>botmesh is ESM-only. Use <code>import</code>, and add <code>&quot;type&quot;: &quot;module&quot;</code> to your <code>package.json</code> (or use <code>.mjs</code> files). With TypeScript, set <code>&quot;module&quot;: &quot;nodenext&quot;</code>.</p><h3 id="pnpm-add-botmesh-core-installs-an-older-build" tabindex="-1"><code>pnpm add @botmesh/core</code> installs an older build <a class="header-anchor" href="#pnpm-add-botmesh-core-installs-an-older-build" aria-label="Permalink to &quot;`pnpm add @botmesh/core` installs an older build&quot;">​</a></h3><p>botmesh is in beta: a plain install gets the beta, and <code>@beta</code> always resolves to the newest one (<code>latest</code> is moved by hand after each publish). Right after a publish, a plain install can still get the previous beta until <code>latest</code> is moved, and a project that mixes builds can fail on missing exports or peer ranges. Check the tags with <code>pnpm view @botmesh/core dist-tags</code> and install the newest beta with the tag, for example <code>pnpm add @botmesh/core@beta @botmesh/baileys@beta</code>. See <a href="./getting-started">Installation</a>.</p><h2 id="whatsapp-web-baileys" tabindex="-1">WhatsApp Web (Baileys) <a class="header-anchor" href="#whatsapp-web-baileys" aria-label="Permalink to &quot;WhatsApp Web (Baileys)&quot;">​</a></h2><h3 id="the-connection-closes-with-428-before-the-qr-appears" tabindex="-1">The connection closes with <code>428</code> before the QR appears <a class="header-anchor" href="#the-connection-closes-with-428-before-the-qr-appears" aria-label="Permalink to &quot;The connection closes with `428` before the QR appears&quot;">​</a></h3><p>WhatsApp closes connections that use an outdated handshake with <code>428 Connection Terminated</code>. Check two things:</p><ol><li><code>@whiskeysockets/baileys</code> resolves to <code>7.0.0-rc14</code> or newer in your lockfile (<code>pnpm why @whiskeysockets/baileys</code>). <code>@botmesh/baileys</code> pins a working version; an override or an old lockfile can bring back an older one.</li><li>You do not pass a custom <code>browser</code> tuple. Leave <code>browser</code> undefined (or use a preset such as <code>&#39;macOS&#39;</code>): non-standard identities can be refused with <code>428</code>.</li></ol><p>The provider also needs to reach <code>wss://web.whatsapp.com</code> and, at startup, <code>raw.githubusercontent.com</code> (to read the current WhatsApp Web version).</p><h3 id="the-qr-never-shows-up" tabindex="-1">The QR never shows up <a class="header-anchor" href="#the-qr-never-shows-up" aria-label="Permalink to &quot;The QR never shows up&quot;">​</a></h3><p>Print it in the terminal or save it as a PNG, or handle the <code>qr</code> event yourself:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> provider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaileysProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ session: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-bot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, qr: { terminal: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, file: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./qr.png&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } })</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;qr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">artifact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Scan or type this:&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, artifact)) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// a QR string or a pairing code</span></span></code></pre></div><p>To link without a QR, pass <code>pairingPhoneNumber: &#39;+57300…&#39;</code> and type the code from the <code>qr</code> event in WhatsApp → Linked devices.</p><h3 id="the-bot-asks-for-a-new-qr-or-stops-reconnecting" tabindex="-1">The bot asks for a new QR, or stops reconnecting <a class="header-anchor" href="#the-bot-asks-for-a-new-qr-or-stops-reconnecting" aria-label="Permalink to &quot;The bot asks for a new QR, or stops reconnecting&quot;">​</a></h3><p>The provider reports the reason on the <code>connection</code> event:</p><table tabindex="0"><thead><tr><th><code>reason</code></th><th>What happened</th><th>What to do</th></tr></thead><tbody><tr><td><code>sessionInvalid</code></td><td>The device was unlinked from the phone, or the session files are corrupt. The provider deletes that session&#39;s folder.</td><td>Scan the new QR.</td></tr><tr><td><code>sessionTakenOver</code></td><td>Another process uses the same session, or WhatsApp forbade it. The provider does <strong>not</strong> reconnect, to protect the number.</td><td>Stop the other instance (an old deploy, a second terminal), then start again.</td></tr><tr><td><code>transient</code></td><td>A network drop. The provider retries with backoff (up to 10 attempts by default).</td><td>Nothing; tune <code>reconnect: { maxAttempts, baseMs, capMs }</code> if needed.</td></tr></tbody></table><h3 id="the-same-person-shows-up-with-two-ids-or-a-flow-stops-waiting-for-the-answer" tabindex="-1">The same person shows up with two ids, or a flow stops waiting for the answer <a class="header-anchor" href="#the-same-person-shows-up-with-two-ids-or-a-flow-stops-waiting-for-the-answer" aria-label="Permalink to &quot;The same person shows up with two ids, or a flow stops waiting for the answer&quot;">​</a></h3><p>WhatsApp addresses people by phone number (<strong>PN</strong>, <code>…@s.whatsapp.net</code>) and by an opaque id (<strong>LID</strong>, <code>…@lid</code>), and the form can change between messages. <code>@botmesh/baileys</code> resolves this before the bot sees the message: <code>ctx.sender</code> and <code>ctx.from</code> use the PN whenever it is known, otherwise the LID, and the raw values are in <code>ctx.senderInfo.platformData</code> (<code>phoneNumber</code>, <code>lid</code>).</p><ul><li><strong>Never key your data on <code>ctx.raw</code></strong> (the raw <code>remoteJid</code>): use <code>ctx.sender</code> / <code>ctx.from</code>.</li><li><strong>A person who only has a LID</strong> (users with a WhatsApp username) keeps a stable LID id; <code>platformData.phoneNumber</code> is <code>undefined</code>. Do not assume <code>ctx.sender</code> is a phone number.</li><li><strong>If the PN is learned mid-conversation</strong>, the person switches to the PN id and a conversation started under the LID no longer receives their messages. Give flows a <code>.timeout()</code> (or <code>timeout</code> on <code>c.ask</code>) so it closes itself, and store both <code>platformData.phoneNumber</code> and <code>platformData.lid</code> if you keep per-person records.</li><li><strong>Access lists match exact ids</strong>: add the full id (<code>573001234567@s.whatsapp.net</code>, or the <code>@lid</code> id), not a bare number. Build ids with <code>toJid(&#39;+57 300 123 4567&#39;)</code>.</li></ul><h3 id="messages-fail-with-a-rate-limit-error-or-replies-are-slow" tabindex="-1">Messages fail with a rate-limit error, or replies are slow <a class="header-anchor" href="#messages-fail-with-a-rate-limit-error-or-replies-are-slow" aria-label="Permalink to &quot;Messages fail with a rate-limit error, or replies are slow&quot;">​</a></h3><p>The Baileys provider queues sends in a token bucket (5 per chat every 10 s and 50 in total per minute by default) to lower the risk of a ban. A send that waits longer than <code>rateLimit.maxWait</code> (30 s) rejects with <code>RateLimitedError</code>. Spread bulk sends with <code>bot.broadcast()</code> (batches, pauses, retries) instead of a loop of <code>bot.send()</code>. See <a href="./rate-limiting">Rate limiting</a>.</p><h2 id="whatsapp-cloud-api-messenger-and-instagram" tabindex="-1">WhatsApp Cloud API, Messenger and Instagram <a class="header-anchor" href="#whatsapp-cloud-api-messenger-and-instagram" aria-label="Permalink to &quot;WhatsApp Cloud API, Messenger and Instagram&quot;">​</a></h2><h3 id="webhook-signature-mismatch-403" tabindex="-1">Webhook signature mismatch (403) <a class="header-anchor" href="#webhook-signature-mismatch-403" aria-label="Permalink to &quot;Webhook signature mismatch (403)&quot;">​</a></h3><p>Every webhook answered with <code>403</code> means the <code>X-Hub-Signature-256</code> check failed. Meta signs the exact bytes it sends, so:</p><ul><li>Pass the <strong>raw body</strong> to <code>provider.ingest(body, headers)</code>: <code>express.raw({ type: &#39;application/json&#39; })</code>, the <code>Buffer</code> you collect with <code>node:http</code>, or the raw body of your framework. A body parsed by <code>express.json()</code> and re-serialized never matches (with <code>appSecret</code> set, an already-parsed object is answered with <code>400</code>).</li><li>Use the <strong>App Secret</strong> of the app that owns the webhook (App settings → Basic), not the access token or the verify token.</li><li>Do not put a proxy that rewrites the body (compression, JSON pretty-printing) in front of the endpoint.</li></ul><p>For local tests only, <code>allowUnsignedWebhooks: true</code> turns the check off.</p><h3 id="meta-cannot-verify-the-webhook-url" tabindex="-1">Meta cannot verify the webhook URL <a class="header-anchor" href="#meta-cannot-verify-the-webhook-url" aria-label="Permalink to &quot;Meta cannot verify the webhook URL&quot;">​</a></h3><p>The <code>GET</code> handshake compares <code>hub.verify_token</code> with the provider&#39;s <code>verifyToken</code>. Answer with <code>provider.verifyChallenge(req.query)</code> and <code>403</code> when it returns <code>null</code>. The URL must be public HTTPS (use a tunnel such as <code>cloudflared</code> or <code>ngrok</code> during development).</p><h3 id="outsidesessionwindowerror" tabindex="-1"><code>OutsideSessionWindowError</code> <a class="header-anchor" href="#outsidesessionwindowerror" aria-label="Permalink to &quot;`OutsideSessionWindowError`&quot;">​</a></h3><p>More than 24 hours passed since the user&#39;s last message, and Meta only accepts approved templates. Send a <code>{ kind: &#39;template&#39;, … }</code> or let the provider&#39;s <code>sessionWindow</code> reopen the conversation for you. See <a href="./session-window">WhatsApp 24h window</a>.</p><h3 id="recipientunreachableerror-with-a-test-number" tabindex="-1"><code>RecipientUnreachableError</code> with a test number <a class="header-anchor" href="#recipientunreachableerror-with-a-test-number" aria-label="Permalink to &quot;`RecipientUnreachableError` with a test number&quot;">​</a></h3><p>A test number can only write to the numbers listed under API setup → &quot;To&quot; in the Meta dashboard (Graph code <code>131030</code>). Add the recipient there.</p><h3 id="the-access-token-is-invalid-or-expired-check-the-configured-phone-number-id" tabindex="-1">&quot;the access token is invalid or expired&quot; / &quot;check the configured phone number id&quot; <a class="header-anchor" href="#the-access-token-is-invalid-or-expired-check-the-configured-phone-number-id" aria-label="Permalink to &quot;&quot;the access token is invalid or expired&quot; / &quot;check the configured phone number id&quot;&quot;">​</a></h3><p>Graph code <code>190</code> is an invalid or expired access token: use a permanent system-user token with <code>whatsapp_business_messaging</code>. Code <code>100</code>/<code>33</code> means the <code>phoneNumberId</code> does not exist or the token cannot reach it: copy the <strong>phone number id</strong> from API setup (it is not the phone number).</p><h3 id="rate-limits-130429-131056-80007" tabindex="-1">Rate limits (<code>130429</code>, <code>131056</code>, <code>80007</code>…) <a class="header-anchor" href="#rate-limits-130429-131056-80007" aria-label="Permalink to &quot;Rate limits (`130429`, `131056`, `80007`…)&quot;">​</a></h3><p>They arrive as <code>RateLimitedError</code> with <code>retryAfterMs</code>. A short wait on a <code>ctx</code> send is retried once (<code>BotConfig.rateLimitRetry</code>), and <code>bot.broadcast()</code> retries per chat (<code>retries</code>, default 3). For bulk traffic, lower <code>concurrency</code> and add <code>delayBetween</code>.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><h3 id="_409-conflict-and-the-bot-stops-receiving-updates" tabindex="-1"><code>409 Conflict</code> and the bot stops receiving updates <a class="header-anchor" href="#_409-conflict-and-the-bot-stops-receiving-updates" aria-label="Permalink to &quot;`409 Conflict` and the bot stops receiving updates&quot;">​</a></h3><p>Two processes poll the same token (or a webhook is set while you poll). The provider stops on purpose (<code>sessionTakenOver</code>). Stop the other instance, or remove the webhook with <code>deleteWebhook</code> before using long polling.</p><h3 id="check-the-bot-token-and-baseurl-404" tabindex="-1">&quot;check the bot token and baseUrl&quot; (404) <a class="header-anchor" href="#check-the-bot-token-and-baseurl-404" aria-label="Permalink to &quot;&quot;check the bot token and baseUrl&quot; (404)&quot;">​</a></h3><p>The token is malformed (copy it again from @BotFather) or <code>baseUrl</code> points at a wrong path.</p><h3 id="webhook-answered-with-401" tabindex="-1">Webhook answered with <code>401</code> <a class="header-anchor" href="#webhook-answered-with-401" aria-label="Permalink to &quot;Webhook answered with `401`&quot;">​</a></h3><p>The <code>X-Telegram-Bot-Api-Secret-Token</code> header does not match <code>webhookSecret</code>. Pass the same value as <code>secret_token</code> to <code>setWebhook</code>.</p><h2 id="the-bot-itself" tabindex="-1">The bot itself <a class="header-anchor" href="#the-bot-itself" aria-label="Permalink to &quot;The bot itself&quot;">​</a></h2><h3 id="botnotrunningerror-bot-is-not-running" tabindex="-1"><code>BotNotRunningError: bot is not running</code> <a class="header-anchor" href="#botnotrunningerror-bot-is-not-running" aria-label="Permalink to &quot;`BotNotRunningError: bot is not running`&quot;">​</a></h3><p>You sent, edited or deleted a message before <code>await bot.start()</code> or after <code>bot.stop()</code>. Schedule proactive sends from <code>bot.on(&#39;ready&#39;, …)</code> or after <code>start()</code> resolves.</p><h3 id="configvalidationerror-invalid-config-option" tabindex="-1"><code>ConfigValidationError: Invalid config.&lt;option&gt;</code> <a class="header-anchor" href="#configvalidationerror-invalid-config-option" aria-label="Permalink to &quot;`ConfigValidationError: Invalid config.&lt;option&gt;`&quot;">​</a></h3><p>An option of <code>new Bot()</code> has the wrong type or an invalid duration. The message names the option (<code>err.field</code>); durations take a string (<code>&#39;30s&#39;</code>, <code>&#39;5m&#39;</code>) or milliseconds.</p><h3 id="plugin-name-is-already-plugged-on-this-bot" tabindex="-1"><code>Plugin &quot;&lt;name&gt;&quot; is already plugged on this bot</code> <a class="header-anchor" href="#plugin-name-is-already-plugged-on-this-bot" aria-label="Permalink to &quot;`Plugin &quot;&lt;name&gt;&quot; is already plugged on this bot`&quot;">​</a></h3><p>Each plugin name can be plugged once. Unplug it first with the function <code>bot.plug()</code> returned, or give every instance <code>multiple: true</code> in its spec.</p><h3 id="bot-when-hi-does-not-match-hi-there" tabindex="-1"><code>bot.when(&#39;hi&#39;)</code> does not match &quot;hi there&quot; <a class="header-anchor" href="#bot-when-hi-does-not-match-hi-there" aria-label="Permalink to &quot;`bot.when(&#39;hi&#39;)` does not match &quot;hi there&quot;&quot;">​</a></h3><p>Text triggers compare by <strong>normalized equality</strong> (case, accents and extra spaces are ignored), not &quot;contains&quot;. Use <code>{ pattern: &#39;hi&#39;, match: &#39;contains&#39; }</code> or a <code>RegExp</code>. See <a href="./triggers">Triggers</a>.</p><h3 id="the-bot-does-not-answer-in-groups" tabindex="-1">The bot does not answer in groups <a class="header-anchor" href="#the-bot-does-not-answer-in-groups" aria-label="Permalink to &quot;The bot does not answer in groups&quot;">​</a></h3><p>Check <code>groupMode</code> (<code>&#39;mentions&#39;</code> and <code>&#39;commands&#39;</code> restrict what the bot answers in groups) and the trigger <code>scope</code>. Group conversations are per participant by default.</p><h3 id="the-built-in-texts-are-in-english" tabindex="-1">The built-in texts are in English <a class="header-anchor" href="#the-built-in-texts-are-in-english" aria-label="Permalink to &quot;The built-in texts are in English&quot;">​</a></h3><p>Timeouts, retries, slash commands and form prompts default to English. Set <code>new Bot({ lang: &#39;es&#39; })</code> for Spanish, or register your own texts with <code>bot.locale()</code>. See <a href="./i18n">Internationalization</a>.</p><h3 id="a-persistent-flow-forgets-where-it-was-after-a-restart" tabindex="-1">A <code>.persistent()</code> flow forgets where it was after a restart <a class="header-anchor" href="#a-persistent-flow-forgets-where-it-was-after-a-restart" aria-label="Permalink to &quot;A `.persistent()` flow forgets where it was after a restart&quot;">​</a></h3><p>The default <code>MemoryStore</code> lives in RAM. Use a durable store (<code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code>, or <code>new MemoryStore({ file })</code>). See <a href="./store">Persistent store</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><ul><li>Turn on debug logs: <code>new Bot({ provider, logger: pino({ level: &#39;debug&#39; }) })</code>. Chat and sender ids are hashed in the bot&#39;s log lines by default (<code>logIds</code>).</li><li>Check the <a href="./faq">FAQ</a> and the package README of your channel.</li><li><a href="https://github.com/andresayac/botmesh/issues" target="_blank" rel="noreferrer">Open an issue</a> with the error message, the package versions (<code>pnpm ls @botmesh/*</code>) and your Node.js version. Never paste tokens or session files.</li></ul>',74)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
